-- Name: admit_patient(integer, character varying); Type: FUNCTION; Schema: public; Owner: oblivious
--

CREATE FUNCTION public.admit_patient(p_bed_id integer, p_patient_username character varying) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_doctor_username VARCHAR(25);
    v_nurse_username VARCHAR(25);
    v_existing_bed_id INTEGER;
BEGIN
    -- Check if the patient already has an occupied or reserved bed
    SELECT bed_id INTO v_existing_bed_id
    FROM beds
    WHERE patient_username = p_patient_username
      AND status IN ('Occupied', 'Reserved');

    IF v_existing_bed_id IS NOT NULL THEN
        RAISE EXCEPTION 'Patient % already has a bed assigned (bed_id=%)', p_patient_username, v_existing_bed_id;
    END IF;

    -- Get doctor and nurse username from the beds/wards tables
    SELECT w.doctor_username, w.nurse_username
    INTO v_doctor_username, v_nurse_username
    FROM beds b
    JOIN wards w ON b.ward_id = w.ward_id
    WHERE b.bed_id = p_bed_id;

    -- Update the bed status and assign patient
    UPDATE beds
    SET status = 'Occupied',
        patient_username = p_patient_username,
        check_in_date = NOW(),
        check_out_date = NULL
    WHERE bed_id = p_bed_id;

    -- Insert into admissions table
    INSERT INTO admissions (
        bed_id,
        patient_username,
        doctor_username,
        nurse_username,
        check_in_date
    ) VALUES (
        p_bed_id,
        p_patient_username,
        v_doctor_username,
        v_nurse_username,
        NOW()
    );
END;
$$;


ALTER FUNCTION public.admit_patient(p_bed_id integer, p_patient_username character varying) OWNER TO oblivious;

