    CREATE TABLE IF NOT EXISTS admissions (
        admission_id SERIAL PRIMARY KEY,
        bed_id INTEGER NOT NULL REFERENCES beds(bed_id),
        patient_username VARCHAR(25) NOT NULL REFERENCES patients(username),
        doctor_username VARCHAR(25) REFERENCES users(username),
        nurse_username VARCHAR(25) REFERENCES users(username),
        check_in_date TIMESTAMP NOT NULL,
        check_out_date TIMESTAMP
