--
-- Name: create_discharge_request(integer); Type: FUNCTION; Schema: public; Owner: oblivious
--

CREATE FUNCTION public.create_discharge_request(p_admission_id integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_discharge_id INTEGER;
BEGIN
    -- Check if admission exists
    IF NOT EXISTS (SELECT 1 FROM admissions WHERE admission_id = p_admission_id) THEN
        RAISE EXCEPTION 'Admission with ID % does not exist', p_admission_id;
    END IF;
    
    -- Check if a PENDING discharge request already exists for this admission (case insensitive)
    IF EXISTS (SELECT 1 FROM discharge_requests 
               WHERE admission_id = p_admission_id 
               AND UPPER(status) = 'PENDING') THEN
        RAISE EXCEPTION 'A pending discharge request already exists for admission ID %', p_admission_id;
    END IF;

    -- Insert new discharge request with Bangladesh timezone
    INSERT INTO discharge_requests(admission_id, req_timestamp, status)
    VALUES (
        p_admission_id, 
        (NOW() AT TIME ZONE 'Asia/Dhaka'), 
        'PENDING'  -- Using proper case for consistency
    )
    RETURNING discharge_id INTO v_discharge_id;
    
    RETURN v_discharge_id;
END;
$$;


ALTER FUNCTION public.create_discharge_request(p_admission_id integer) OWNER TO oblivious;

