--
-- Name: discharge_patient(integer); Type: FUNCTION; Schema: public; Owner: oblivious
--

CREATE FUNCTION public.discharge_patient(p_admission_id integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_bed_id INTEGER;
    v_discharge_exists BOOLEAN;
    v_dhaka_timestamp TIMESTAMP;
BEGIN
    -- Get current timestamp in Dhaka timezone
    v_dhaka_timestamp := (NOW() AT TIME ZONE 'Asia/Dhaka');
    
    -- Find the bed_id associated with this admission
    SELECT bed_id INTO v_bed_id
    FROM admissions
    WHERE admission_id = p_admission_id;
    
    -- Check if the admission exists
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Admission with ID % not found', p_admission_id;
    END IF;
    
    -- Check if the patient has already been discharged
    IF EXISTS (
        SELECT 1 
        FROM admissions 
        WHERE admission_id = p_admission_id AND check_out_date IS NOT NULL
    ) THEN
        RAISE EXCEPTION 'Patient has already been discharged';
    END IF;
    
    -- Update check_out_date in admissions table with Dhaka timezone
    UPDATE admissions
    SET check_out_date = v_dhaka_timestamp
    WHERE admission_id = p_admission_id;
    
    -- Update bed status to 'Vacant' (not 'Available') and clear patient_username
    UPDATE beds
    SET status = 'Vacant', 
        patient_username = NULL,
        check_out_date = v_dhaka_timestamp
    WHERE bed_id = v_bed_id;
    
    -- Check if there are any pending discharge requests for this admission
    SELECT EXISTS (
        SELECT 1 
        FROM discharge_requests 
        WHERE admission_id = p_admission_id AND UPPER(status) = 'PENDING'
    ) INTO v_discharge_exists;
    
    -- If a pending discharge request exists, update its status to 'Approved'
    IF v_discharge_exists THEN
        UPDATE discharge_requests
        SET status = 'APPROVED'
        WHERE admission_id = p_admission_id AND UPPER(status) = 'PENDING';
    END IF;
    
    RETURN TRUE;
EXCEPTION
    WHEN OTHERS THEN
        -- Log error and rethrow
        RAISE;
END;
$$;


ALTER FUNCTION public.discharge_patient(p_admission_id integer) OWNER TO oblivious;

