--
-- Name: find_bed_for_patient(character varying, character varying); Type: FUNCTION; Schema: public; Owner: oblivious
--

CREATE FUNCTION public.find_bed_for_patient(p_ward_type character varying, p_bed_type character varying) RETURNS TABLE(found boolean, bed_count integer, beds jsonb)
    LANGUAGE plpgsql
    AS $$
DECLARE
    is_any_bed_type BOOLEAN;
    matching_beds JSONB;
    total_count INTEGER;
BEGIN
    -- Check if bed_type is "any" (case-insensitive)
    is_any_bed_type := LOWER(p_bed_type) = 'any';
    
    -- Find matching beds
    SELECT 
        COUNT(b.bed_id),
        COALESCE(
            jsonb_agg(
                jsonb_build_object(
                    'bed_id', b.bed_id,
                    'bed_no', b.bed_no,
                    'ward_no', w.ward_no,
                    'ward_name', w.ward_name,
                    'ward_type', w.ward_type,
                    'bed_type', b.bed_type,
                    'cost_per_day', b.cost_per_day,
                    'doctor_username', w.doctor_username
                )
            ),
            '[]'::jsonb
        )
    INTO 
        total_count, matching_beds
    FROM 
        beds b
    JOIN 
        wards w ON b.ward_id = w.ward_id
    WHERE 
        w.ward_type = p_ward_type
        AND b.status = 'Vacant'
        AND (is_any_bed_type OR b.bed_type = p_bed_type);
    
    -- Return results
    found := total_count > 0;
    bed_count := total_count;
    beds := matching_beds;
    
    RETURN NEXT;
    RETURN;
END;
$$;


ALTER FUNCTION public.find_bed_for_patient(p_ward_type character varying, p_bed_type character varying) OWNER TO oblivious;

