--
-- Name: get_current_admission(character varying); Type: FUNCTION; Schema: public; Owner: oblivious
--

CREATE FUNCTION public.get_current_admission(p_patient_username character varying) RETURNS TABLE(has_active_admission boolean, admission_id integer, bed_id integer, ward_no character varying, ward_name character varying, ward_type character varying, patient_name character varying, doctor_username character varying, nurse_username character varying, check_in_date timestamp without time zone, check_out_date timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- First check if patient has active admission
    PERFORM 1
    FROM admissions a
    WHERE a.patient_username = p_patient_username
      AND a.check_out_date IS NULL
    LIMIT 1;
    
    -- If no active admission, return a row with has_active_admission = false
    IF NOT FOUND THEN
        RETURN QUERY SELECT 
            false, 
            NULL::integer, 
            NULL::integer, 
            NULL::varchar, 
            NULL::varchar, 
            NULL::varchar, 
            NULL::varchar, 
            NULL::varchar, 
            NULL::varchar, 
            NULL::timestamp, 
            NULL::timestamp;
        RETURN;
    END IF;
    
    -- If there is an active admission, return the details
    RETURN QUERY
    WITH latest_admission AS (
        SELECT a.*, b.ward_id
        FROM admissions a
        JOIN beds b ON a.bed_id = b.bed_id
        WHERE a.patient_username = p_patient_username
          AND a.check_out_date IS NULL
        ORDER BY a.check_in_date DESC
        LIMIT 1
    )
    SELECT
        true AS has_active_admission,
        la.admission_id,
        la.bed_id,
        w.ward_no,
        w.ward_name,
        w.ward_type,
        la.patient_name,
        la.doctor_username,
        la.nurse_username,
        la.check_in_date,
        la.check_out_date
    FROM latest_admission la
    LEFT JOIN wards w ON la.ward_id = w.ward_id;
END;
$$;


