--
-- Name: get_discharge_requests(text); Type: FUNCTION; Schema: public; Owner: oblivious
--

CREATE FUNCTION public.get_discharge_requests(p_doctor_username text) RETURNS TABLE(discharge_id integer, admission_id integer, patient_username character varying, patient_name text, req_timestamp timestamp without time zone, status character varying, bed_number integer, ward_name character varying, request_date text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        dr.discharge_id,
        dr.admission_id,
        a.patient_username,
        public.get_name(a.patient_username) AS patient_name,
        dr.req_timestamp,
        dr.status,
        a.bed_id AS bed_number,
        w.ward_name,
        TO_CHAR(dr.req_timestamp AT TIME ZONE 'Asia/Dhaka', 'YYYY-MM-DD HH24:MI:SS') AS request_date
    FROM 
        discharge_requests dr
    JOIN 
        admissions a ON dr.admission_id = a.admission_id
    JOIN
        beds b ON a.bed_id = b.bed_id
    JOIN
        wards w ON b.ward_id = w.ward_id
    WHERE 
        a.doctor_username = p_doctor_username
        AND dr.status = 'PENDING'  -- PostgreSQL is case-sensitive by default
    ORDER BY
        dr.req_timestamp DESC;
END;
$$;


ALTER FUNCTION public.get_discharge_requests(p_doctor_username text) OWNER TO oblivious;

--
-- Name: get_doctor_assigned_beds(character varying); Type: FUNCTION; Schema: public; Owner: oblivious
--

CREATE FUNCTION public.get_doctor_assigned_beds(p_doctor_username character varying) RETURNS TABLE(bed_id integer, bed_no character varying, ward_id integer, ward_no character varying, ward_name character varying, ward_type character varying, patient_username character varying, patient_name character varying, nurse_username character varying, status character varying, bed_type character varying, cost_per_day numeric, check_in_date timestamp without time zone, check_out_date timestamp without time zone, admission_id integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Set the timezone explicitly to Dhaka, Bangladesh
    SET LOCAL timezone TO 'Asia/Dhaka';
    
    RETURN QUERY 
    SELECT 
        b.bed_id,
        b.bed_no,
        w.ward_id,
        w.ward_no,
        w.ward_name,
        w.ward_type,
        b.patient_username,
        a.patient_name,
        COALESCE(a.nurse_username, w.nurse_username) AS nurse_username,
        b.status,
        b.bed_type,
        b.cost_per_day,
        b.check_in_date,
        b.check_out_date,
        a.admission_id
    FROM 
        beds b
    JOIN 
        wards w ON b.ward_id = w.ward_id
    LEFT JOIN 
        admissions a ON b.bed_id = a.bed_id AND a.check_out_date IS NULL
    WHERE 
        (w.doctor_username = p_doctor_username OR
         a.doctor_username = p_doctor_username)
    ORDER BY 
        w.ward_name, b.bed_no;
END;
$$;


ALTER FUNCTION public.get_doctor_assigned_beds(p_doctor_username character varying) OWNER TO oblivious;

