--
-- Name: schedule_appointment(character varying, character varying, date); Type: FUNCTION; Schema: public; Owner: oblivious
--

CREATE FUNCTION public.schedule_appointment(p_patient_username character varying, p_doctor_username character varying, p_appointment_date date) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    DOCTOR_START TIME WITHOUT TIME ZONE;
    DOCTOR_END TIME WITHOUT TIME ZONE;
    AVG_TIME_INTERVAL INTERVAL;
    LAST_APPOINTMENT_TIME TIME WITHOUT TIME ZONE;
    NEXT_AVAILABLE_TIME TIME WITHOUT TIME ZONE;
    NEXT_DAY_START TIME WITHOUT TIME ZONE;
    MAX_APPOINTMENTS INT;
    EXISTING_APPOINTMENTS INT;
BEGIN
    -- Check if the patient already has an appointment on the given date
    IF EXISTS (
        SELECT
            1
        FROM
            APPOINTMENTS
        WHERE
            PATIENT_USERNAME = P_PATIENT_USERNAME
            AND APPOINTMENT_DATE = P_APPOINTMENT_DATE
    ) THEN
        RAISE EXCEPTION
        'Patient % already has an appointment on %', P_PATIENT_USERNAME, P_APPOINTMENT_DATE;
    END IF;

    -- Get doctor's visiting time and average appointment duration
    SELECT
        VISITING_TIME_START,
        VISITING_TIME_END,
        AVG_TIME * INTERVAL '1 minute'
    INTO
        DOCTOR_START,
        DOCTOR_END,
        AVG_TIME_INTERVAL
    FROM
        DOCTORS
    WHERE
        USERNAME = P_DOCTOR_USERNAME;

    -- Calculate the maximum appointments per day for the doctor
    MAX_APPOINTMENTS := calculate_max_appointments_per_day(P_DOCTOR_USERNAME);

    -- Count the number of existing appointments for the doctor on the specified date
    SELECT COUNT(*) INTO EXISTING_APPOINTMENTS
    FROM APPOINTMENTS
    WHERE DOCTOR_USERNAME = P_DOCTOR_USERNAME
      AND APPOINTMENT_DATE = P_APPOINTMENT_DATE;

    -- Check if the doctor has reached the maximum number of appointments
    IF EXISTING_APPOINTMENTS >= MAX_APPOINTMENTS THEN
        RAISE EXCEPTION
        'Doctor % has reached the maximum number of appointments for %', P_DOCTOR_USERNAME, P_APPOINTMENT_DATE;
    END IF;

    -- Check for the last appointment time for the doctor
    SELECT
        MAX(APPOINTMENT_TIME)
    INTO
        LAST_APPOINTMENT_TIME
    FROM
        APPOINTMENTS
    WHERE
        DOCTOR_USERNAME = P_DOCTOR_USERNAME
        AND APPOINTMENT_DATE = P_APPOINTMENT_DATE;

    -- Calculate the next available time
    IF LAST_APPOINTMENT_TIME IS NOT NULL THEN
        NEXT_AVAILABLE_TIME := LAST_APPOINTMENT_TIME + AVG_TIME_INTERVAL;
    ELSE
        NEXT_AVAILABLE_TIME := DOCTOR_START;
    END IF;

    -- Handle case where the doctor_end is on the next day
    NEXT_DAY_START := DOCTOR_END + INTERVAL '1 day';

    -- Check if there is no available time within the doctor's schedule
    IF NEXT_AVAILABLE_TIME >= DOCTOR_END AND NEXT_AVAILABLE_TIME < NEXT_DAY_START THEN
        RAISE EXCEPTION
        'No available time for appointment on % with doctor %', P_APPOINTMENT_DATE, P_DOCTOR_USERNAME;
    END IF;

    -- Insert the appointment
    INSERT INTO APPOINTMENTS (
        PATIENT_USERNAME,
        DOCTOR_USERNAME,
        APPOINTMENT_DATE,
        APPOINTMENT_TIME
    ) VALUES (
        P_PATIENT_USERNAME,
        P_DOCTOR_USERNAME,
        P_APPOINTMENT_DATE,
        NEXT_AVAILABLE_TIME
    );
END;
$$;


ALTER FUNCTION public.schedule_appointment(p_patient_username character varying, p_doctor_username character varying, p_appointment_date date) OWNER TO oblivious;

--
-- Name: search_donor(character); Type: FUNCTION; Schema: public; Owner: oblivious
--

CREATE FUNCTION public.search_donor(_blood_group character DEFAULT '*'::bpchar) RETURNS TABLE(name character varying, blood_group character varying, complexities text, last_donation timestamp without time zone, phone_no character[], approximate_distance double precision)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        b.name,
        b.blood_group,
        b.complexities,
        b.last_donation,
        b.phone_no,
        ROUND(CAST(haversine_distance(b.general_location, h.hospital_location) AS numeric), 2)::float AS approximate_distance
    FROM
        blood_repo b,
        hospital_info h
    WHERE
        (_blood_group = '*' OR b.blood_group = _blood_group) -- Allow all blood groups when _blood_group = '*'
        AND b.last_donation <= NOW() - INTERVAL '3 months'
    ORDER BY
        approximate_distance ASC;
END;
$$;


ALTER FUNCTION public.search_donor(_blood_group character) OWNER TO oblivious;

--
-- Name: set_bed_to_maintenance(); Type: FUNCTION; Schema: public; Owner: oblivious
--

CREATE FUNCTION public.set_bed_to_maintenance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_bed_id INTEGER;
    v_dhaka_timestamp TIMESTAMP;
    v_valid_status VARCHAR;
BEGIN
    -- Get current timestamp in Dhaka timezone
    v_dhaka_timestamp := (NOW() AT TIME ZONE 'Asia/Dhaka');
    
    -- Find the bed_id associated with the admission
    SELECT bed_id INTO v_bed_id
    FROM admissions
    WHERE admission_id = NEW.admission_id;
    
    -- Check what valid status values are available in the database
    -- You might need to adjust this query based on your database schema
    -- This is for debugging purposes
    RAISE NOTICE 'Attempting to update bed_id: % to maintenance status', v_bed_id;
    
    -- Set bed to maintenance status - use the exact case and spelling from your enum
    -- Try 'maintenance' (lowercase) if 'Maintenance' doesn't work
    UPDATE beds
    SET status = 'maintenance',  -- Try lowercase if uppercase doesn't work
        maintenance_start_time = v_dhaka_timestamp
    WHERE bed_id = v_bed_id;
    
    -- Check if the update succeeded
    IF NOT FOUND THEN
        RAISE NOTICE 'Bed update failed - bed_id: % not found', v_bed_id;
    END IF;
    
    RETURN NEW;
EXCEPTION
    WHEN others THEN
        RAISE NOTICE 'Error in set_bed_to_maintenance: %', SQLERRM;
        RETURN NEW;
END;
$$;


ALTER FUNCTION public.set_bed_to_maintenance() OWNER TO oblivious;

--
-- Name: show_past_appointments(character varying, character varying); Type: FUNCTION; Schema: public; Owner: oblivious
--

CREATE FUNCTION public.show_past_appointments(p_username character varying, p_user_type character varying) RETURNS TABLE(appointment_id integer, appointment_date date, appointment_time time without time zone, related_user character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF p_user_type = 'doctor' THEN
        RETURN QUERY
        SELECT 
            a.appointment_id,
            a.appointment_date,
            a.appointment_time,
            a.patient_username AS related_user
        FROM appointments a
        INNER JOIN prescriptions p ON a.appointment_id = p.appointment_id
        WHERE a.doctor_username = p_username
        ORDER BY a.appointment_date DESC, a.appointment_time DESC;
    ELSIF p_user_type = 'patient' THEN
        RETURN QUERY
        SELECT 
            a.appointment_id,
            a.appointment_date,
            a.appointment_time,
            a.doctor_username AS related_user
        FROM appointments a
        INNER JOIN prescriptions p ON a.appointment_id = p.appointment_id
        WHERE a.patient_username = p_username
        ORDER BY a.appointment_date DESC, a.appointment_time DESC;
    ELSE
        RAISE EXCEPTION 'Invalid user type: %. Expected ''doctor'' or ''patient''.', p_user_type;
    END IF;
END;
$$;


