-- Name: show_upcoming_appointments(character varying, character varying); Type: FUNCTION; Schema: public; Owner: oblivious
--

CREATE FUNCTION public.show_upcoming_appointments(p_username character varying, p_user_type character varying) RETURNS TABLE(appointment_id integer, appointment_date date, appointment_time time without time zone, with_user character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF p_user_type = 'doctor' THEN
        RETURN QUERY
        SELECT 
            a.appointment_id,
            a.appointment_date,
            a.appointment_time,
            a.patient_username AS with_user
        FROM appointments a
        WHERE a.doctor_username = p_username
          AND (a.appointment_date > CURRENT_DATE 
               OR (a.appointment_date = CURRENT_DATE AND a.appointment_time >= CURRENT_TIME))
          AND NOT EXISTS (
              SELECT 1 FROM prescriptions p WHERE p.appointment_id = a.appointment_id
          )
        ORDER BY a.appointment_date, a.appointment_time;
    ELSIF p_user_type = 'patient' THEN
        RETURN QUERY
        SELECT 
            a.appointment_id,
            a.appointment_date,
            a.appointment_time,
            a.doctor_username AS with_user
        FROM appointments a
        WHERE a.patient_username = p_username
          AND (a.appointment_date > CURRENT_DATE 
               OR (a.appointment_date = CURRENT_DATE AND a.appointment_time >= CURRENT_TIME))
          AND NOT EXISTS (
              SELECT 1 FROM prescriptions p WHERE p.appointment_id = a.appointment_id
          )
        ORDER BY a.appointment_date, a.appointment_time;
    ELSE
        RAISE EXCEPTION 'Invalid user type: %. Expected ''doctor'' or ''patient''.', p_user_type;
    END IF;
END;
$$;


